mapper.select:
SELECT work_id, title, work_type, summary
FROM sys_work
WHERE work_id = #{workId}

mapper.update:
UPDATE sys_work_chapter c
SET c.status = #{status}
WHERE c.work_id = #{workId}
  AND c.word_count > 0
  AND #{reviewId} = (
      SELECT r.review_id FROM sys_review_record r
      WHERE r.target_type = 'work' AND r.target_id = #{workId}
      ORDER BY r.created_at DESC, r.review_id DESC LIMIT 1
  )
